def minExtraChar(s, dictionary):
    n = len(s)
    dp = [0] * (n + 1)
    for i in range(1, n + 1):
        dp[i] = dp[i - 1] + 1
        for word in dictionary:
            if s[i - len(word):i] == word:
                dp[i] = min(dp[i], dp[i - len(word)])
    return dp[n]

