def find_original_array(derived):
    n = len(derived)
    if n % 2 != 0:
        return False
    count = [0] * 200001
    for d in derived:
        count[d] += 1
    for d in derived:
        if count[d] == 0:
            continue
        if d == 0 and count[d] % 2 != 0:
            return False
        if d % 2 == 0 and count[d] == 0:
            return False
        if d % 2 == 1 and count[d] == 0:
            return False
        if d % 2 == 0 and count[d - 1] == 0:
            return False
        if d % 2 == 1 and count[d + 1] == 0:
            return False
        count[d] -= 1
        if d % 2 == 0:
            count[d - 1] -= 1
        else:
            count[d + 1] -= 1
    return True

