def longestEqualSubarray(nums, k):
    n = len(nums)
    freq = {}
    max_len = 0
    for i in range(n):
        freq[nums[i]] = freq.get(nums[i], 0) + 1
        while freq[nums[i]] > i + 1:
            freq[nums[i - 1]] -= 1
            if freq[nums[i - 1]] == 0:
                del freq[nums[i - 1]]
        max_len = max(max_len, i + 1 - (freq[nums[i]] - 1))
        if freq[nums[i]] - 1 <= k:
            max_len = max(max_len, i + 1)
    return max_len

def numSpecialPerms(nums):
    MOD = 10**9 + 7
    n = len(nums)
    nums.sort()
    dp = [[0]*n for _ in range(1<<n)]
    dp[0][0] = 1
    for mask in range(1<<n):
        for i in range(n):
            if mask & (1<<i):
                for j in range(n):
                    if mask & (1<<j) and (nums[i] % nums[j] == 0 or nums[j] % nums[i] == 0):
                        dp[mask | (1<<j)][j] = (dp[mask | (1<<j)][j] + dp[mask][i]) % MOD
    return sum(dp[-1]) % MOD

