def count_ways(n, x):
    MOD = 10**9 + 7
    dp = [0] * (n + 1)
    dp[0] = 1
    for i in range(1, n + 1):
        for j in range(1, i + 1):
            if i >= j**x:
                dp[i] = (dp[i] + dp[i - j**x]) % MOD
    return dp[n]

def longestValidSubstring(word, forbidden):
    forbidden = set(''.join(sorted(f)) for f in forbidden)
    n = len(word)
    max_len = 0
    for i in range(n):
        for j in range(i, n):
            if ''.join(sorted(word[i:j+1])) in forbidden:
                break
        else:
            max_len = max(max_len, j - i + 1)
    return max_len

