def maximumBeauty(nums, k):
    from collections import Counter
    counter = Counter(nums)
    max_beauty = 0
    for num, count in counter.items():
        max_beauty = max(max_beauty, count)
        for i in range(num - k, num + k + 1):
            if i in counter:
                max_beauty = max(max_beauty, count + counter[i])
    return max_beauty

