def countWays(s, t, k):
    MOD = 10**9 + 7
    n = len(s)
    dp = [[0] * (k + 1) for _ in range(n + 1)]
    dp[0][0] = 1
    for i in range(1, n + 1):
        for j in range(k, -1, -1):
            if j >= i:
                dp[i][j] = (dp[i - 1][j] + dp[i - 1][j - i]) % MOD
            else:
                dp[i][j] = dp[i - 1][j]
    return dp[n][k]

