def numGoodPartitions(nums):
    MOD = 10**9 + 7
    n = len(nums)
    dp = [0] * n
    dp[0] = 1
    for i in range(1, n):
        if nums[i] != nums[i-1]:
            dp[i] = dp[i-1] + 1
        else:
            dp[i] = dp[i-1]
    return sum(dp) % MOD

def maxSubsetSize(nums):
