def return_to_boundary(nums):
    boundary = 0
    count = 0
    for num in nums:
        if num < 0:
            boundary -= num
        else:
            boundary += num
        if boundary == 0:
            count += 1
    return count

def generate_sequence(N, A):
    while True:
        for i in range(N-1):
            if abs(A[i] - A[i+1]) != 1:
                if A[i] < A[i+1]:
                    A.insert(i+1, A[i]+1)
                    A.insert(i+2, A[i]+2)
                else:
                    A.insert(i+1, A[i]-1)
                    A.insert(i+2, A[i]-2)
                break
        else:
            break
    return A

