def count_non_ddos_subsequences(s):
    MOD = 998244353
    n = len(s)
    dp = [[0] * 26 for _ in range(n + 1)]
    dp[0][0] = 1
    for i in range(1, n + 1):
        if s[i - 1] == '?':
            for j in range(26):
                dp[i][j] = (dp[i - 1][j] + dp[i - 1][j + 1]) % MOD
        else:
            for j in range(26):
                if s[i - 1].isupper():
                    dp[i][j] = (dp[i - 1][j] + dp[i - 1][j + 1]) % MOD
                else:
                    dp[i][j] = (dp[i - 1][j] + dp[i - 1][j + 1] + dp[i - 1][j - 1]) % MOD
    return sum(dp[n]) % MOD

