def process_queries(N, Q, queries):
    graph = {i: [] for i in range(1, N+1)}
    connected = set()
    disconnected = set()

    for query in queries:
        if query[0] == 1:
            u, v = query[1], query[2]
            graph[u].append(v)
            graph[v].append(u)
            connected.add(u)
            connected.add(v)
        elif query[0] == 2:
            v = query[1]
            for u in graph[v]:
                graph[u].remove(v)
                graph[v].remove(u)
            connected.remove(v)
            disconnected.add(v)

    return len(disconnected)


