    dp[0][0] = 1
    for i in range(1, n):
        if s[i] == '(':
            dp[i][0] = dp[i-1][0]
        else:
            dp[i][0] = dp[i-1][0] + dp[i-1][1]
        for j in range(1, i):
            if s[j] == '(':
                dp[i][j] = dp[i-1][j-1] + dp[i-1][j]
