def min_travel_time(N, A, B, C, D):
    # Initialize the distance matrix
    dist = [[0] * N for _ in range(N)]
    for i in range(N):
        for j in range(i+1, N):
            dist[i][j] = dist[j][i] = D[i][j]

    # Initialize the dp array
    dp = [[float('inf')] * N for _ in range(N)]
    for i in range(N):
        dp[i][i] = 0

    # Iterate over all possible paths
    for k in range(N):
        for i in range(N):
            for j in range(i+1, N):
                dp[i][j] = min(dp[i][j], dp[i][k] + dp[k][j] + (dist[i][k] * A + dist[k][j] * B + C))

    return dp[0][N-1]

