def min_operations(N, edges):
    graph = {i: [] for i in range(1, N+1)}
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    leaves = [i for i in range(1, N+1) if len(graph[i]) == 1]
    operations = 0
    while len(leaves) > 1:
        leaf = leaves.pop()
        for neighbor in graph[leaf]:
            graph[neighbor].remove(leaf)
            if len(graph[neighbor]) == 1:
                leaves.append(neighbor)
        operations += 1
    return operations

