        adj[v-1].append(u-1)

    # Sort vertices by W in descending order
    vertices = sorted(range(N), key=lambda x: W[x], reverse=True)

    # Initialize variables
    max_operations = 0
    remaining_pieces = A

    # Perform operations
    for vertex in vertices:
        if remaining_pieces[vertex] > 0:
            # Find a set S of vertices adjacent to vertex such that sum of W of S is less than W[vertex]
            S = []
            for neighbor in adj[vertex]:
                if remaining_pieces[neighbor] > 0:
                    S.append(neighbor)
                    remaining_pieces[neighbor] -= 1
                    if sum(W[i] for i in S) < W[vertex]:
                        break
            if S:
                max_operations += 1
                for i in S:
                    remaining_pieces[i] += 1

